# Script de Inicializacao - Suporte Tecnico API (Windows)\n# Use: powershell -ExecutionPolicy Bypass -File start.ps1\n\nWrite-Host \"🚀 Iniciando Suporte Tecnico API...\" -ForegroundColor Cyan\nWrite-Host \"\"\n\n# Verificar se Node.js esta instalado\nif (-not (Get-Command node -ErrorAction SilentlyContinue)) {\n    Write-Host \"❌ Node.js nao esta instalado. Instale de: https://nodejs.org/\" -ForegroundColor Red\n    exit 1\n}\n\nWrite-Host \"✅ Node.js encontrado: $(node --version)\" -ForegroundColor Green\nWrite-Host \"\"\n\n# Verificar se npm esta instalado\nif (-not (Get-Command npm -ErrorAction SilentlyContinue)) {\n    Write-Host \"❌ npm nao esta instalado\" -ForegroundColor Red\n    exit 1\n}\n\nWrite-Host \"✅ npm encontrado: $(npm --version)\" -ForegroundColor Green\nWrite-Host \"\"\n\n# Instalar dependencias se necessario\nif (-not (Test-Path \"node_modules\")) {\n    Write-Host \"📦 Instalando dependencias...\" -ForegroundColor Yellow\n    npm install\n    Write-Host \"\"\n} else {\n    Write-Host \"✅ Dependencias ja instaladas\" -ForegroundColor Green\n    Write-Host \"\"\n}\n\n# Exibir instrucoes\nWrite-Host \"=== PROXIMOS PASSOS ===\" -ForegroundColor Cyan\nWrite-Host \"\"\nWrite-Host \"1. Para desenvolvimento local:\" -ForegroundColor White\nWrite-Host \"   npm run dev\" -ForegroundColor Yellow\nWrite-Host \"\"\nWrite-Host \"2. Para Cloudflare Pages (recomendado):\" -ForegroundColor White\nWrite-Host \"   npm run pages:dev\" -ForegroundColor Yellow\nWrite-Host \"\"\nWrite-Host \"3. Apos iniciar, acesse:\" -ForegroundColor White\nWrite-Host \"   http://localhost:3000/init.html\" -ForegroundColor Yellow\nWrite-Host \"\"\nWrite-Host \"4. Configure o primeiro admin e dados de teste na pagina de inicializacao\" -ForegroundColor White\nWrite-Host \"\"\nWrite-Host \"📚 Documentacao: Consulte QUICKSTART_PT.md\" -ForegroundColor White\nWrite-Host \"\"\n